import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry type validation', () => {
  it('rejects a wrong-typed field without exposing its value specs/hal-engine-tool-input-validation/spec.md#2', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'ok');
    registry.register(
      {name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}},
      execute
    );
    const response = await registry.execute('weather', {location: 987654321});
    expect(response.result).toMatch(/\\/location.*string/);
    expect(response.result).not.toContain('987654321');
    expect(execute).not.toHaveBeenCalled();
  });
});
EOF
 timeout 300 npm test -- --runTestsByPath src/orchestration/tools/registry.type.test.ts --runInBand"
